/**
 * The lx source list the Wails binding returns.
 *
 * The generated model under frontend/bindings is the source of truth for the wire
 * shape (it is build output, regenerated by `wails3 generate bindings`). These
 * aliases exist so components and their tests import one name instead of each
 * reaching into that directory. See internal/infra/wails/lx_sources_service.go for
 * the Go side of the same contract.
 */
export interface LxSource {
  id: string
  /** Display label; the user may have renamed it. */
  name: string
  /** The stored file's base name (a uuid), for diagnostics. */
  file_name: string
  enabled: boolean
  /** Try order: lower runs first. */
  position: number
  /** Platforms this source registered, as the plugin reported them. */
  providers: string[]
  /** Why the plugin could not load this source; empty means healthy. */
  error: string
}

export interface LxSourcesState {
  sources: LxSource[]
  /** Where imported scripts are copied, shown to the user. */
  directory: string
  /** False when the Lx plugin is installed but turned off. */
  plugin_running: boolean
  /** Why the plugin could not be asked; empty when the list is authoritative. */
  plugin_error: string
}

/**
 * Row labels, translated by the page so the row stays presentation-only and its
 * test needs no i18n instance.
 */
export interface LxSourceRowLabels {
  enable: string
  disable: string
  remove: string
  moveUp: string
  moveDown: string
  providers: string
  noProviders: string
  pluginOff: string
  failed: string
}
